# Content for the GCSE NEA stage introductions (AQA 8552, sections A to F). Used by make_nea_decks.py.
# Worked example throughout: the practice context "Small spaces, big lives" and an invented client, Maya (13),
# who shares a small bedroom with her younger sister. Blocks are placed on a 1600 x 1131 A3 sheet.

CLIENT = 'Example project: Maya, 13, shares a small bedroom'
BANDS_NOTE = 'Bands are a guide to the wording of the AQA criteria, not exact marks.'

